'use strict';
const DICE_ORIENTATIONS={1:[0,0],2:[0,-90],3:[-90,0],4:[90,0],5:[0,90],6:[0,180]};
class DiceVisual{
 constructor(row){this.row=row;this.motion=matchMedia('(prefers-reduced-motion: reduce)');this.angles=[[0,0],[0,0],[0,0]];this.raf=0;const pips={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};row.innerHTML=Array.from({length:3},()=>`<div class="die-slot"><div class="die-camera"><div class="die" role="img">${[1,2,3,4,5,6].map(v=>`<div class="die-face face-${v}" aria-hidden="true">${pips[v].map(p=>`<span class="pip" style="grid-area:${Math.floor(p/3)+1}/${p%3+1}"></span>`).join('')}</div>`).join('')}</div></div><span class="die-shadow"></span></div>`).join('');this.cubes=[...row.querySelectorAll('.die')];this.slots=[...row.querySelectorAll('.die-camera')];this.snap([1,3,5]);}
 paint(){this.cubes.forEach((el,i)=>{const [x,y]=this.angles[i];el.style.transform=`rotateX(${x}deg) rotateY(${y}deg)`;});}
 snap(values){cancelAnimationFrame(this.raf);this.angles=values.map(v=>[...DICE_ORIENTATIONS[v]]);this.slots.forEach(el=>el.style.translate='0 0');this.cubes.forEach((el,i)=>el.setAttribute('aria-label',values[i]+' 点'));this.paint();}
 roll(){cancelAnimationFrame(this.raf);this.cubes.forEach(el=>el.setAttribute('aria-label','旋转中'));this.row.setAttribute('aria-label','三颗骰子旋转中');if(this.motion.matches)return;const start=performance.now(),base=this.angles.map(a=>[...a]);const tick=now=>{const t=(now-start)/1000;this.angles=base.map((a,i)=>[a[0]+t*(650+i*110),a[1]+t*(850-i*100)]);this.slots.forEach((el,i)=>el.style.translate=`0 ${-12-Math.abs(Math.sin(t*7+i*.7))*22}px`);this.paint();this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}
 settle(values,done){cancelAnimationFrame(this.raf);if(this.motion.matches){this.snap(values);done();return;}const start=performance.now(),base=this.angles.map(a=>[...a]),dest=values.map((v,i)=>DICE_ORIENTATIONS[v].map((angle,j)=>(Math.ceil(base[i][j]/360)+1)*360+angle));const lifts=this.slots.map(el=>parseFloat(el.style.translate.split(' ')[1])||0);const tick=now=>{let complete=true;this.angles=base.map((a,i)=>{const t=Math.min(1,(now-start)/(420+i*100));if(t<1)complete=false;const ease=1-Math.pow(1-t,3);this.slots[i].style.translate=`0 ${lifts[i]*(1-ease)+Math.sin(t*Math.PI)*-10}px`;return a.map((v,j)=>v+(dest[i][j]-v)*ease);});this.paint();if(complete){this.snap(values);done();}else this.raf=requestAnimationFrame(tick);};this.raf=requestAnimationFrame(tick);}
}
if(typeof module!=='undefined')module.exports={DICE_ORIENTATIONS};
